void handle_vm_cmdLGetSafeCtrlContent(GameClient& cl, const uint8_t* body, size_t len)
{
    if (len < 1) return;
    uint8_t n = body[0];
    if (1 + n > len) return;
    std::string type((const char*)body + 1, n);
    applyLpc("cmd_get_safe_ctrl_content", {make_int(cl.clientNo), make_string(type)});
}

